void pickupRackTests(){
    using M=Metropolix;Module::ProcessArgs args;args.sampleRate=48000;args.sampleTime=1.f/48000;
    auto make=[](){auto m=std::unique_ptr<M>(new M);for(int k=0;k<2;++k)m->params[M::ctrlParam(k,M::CTRL_DESTINATION)].setValue(metro::CtrlNone);return m;};
    auto frames=[&](M& m,int n=64){for(int f=0;f<n;++f)m.process(args);};
    auto m=make();m->params[M::SCALE].setValue(0);m->params[M::RANGE].setValue(1);m->params[M::PITCH].setValue(.1f);m->params[M::LOAD_PITCH].setValue(M::PitchThru);m->params[M::LOAD_CTRL].setValue(M::CtrlThru);auto saved=m->capturePreset();saved.values[M::PITCH]=.75f;saved.values[M::ctrlParam(0,M::CTRL_VALUE)]=.6f;saved.values[M::ctrlParam(0,M::CTRL_DESTINATION)]=metro::CtrlGateLength;saved.values[M::ctrlParam(0,M::CTRL_ASSIGNMENT)]=0;m->putPreset(0,saved);m->requestPreset(0);m->sendPresetCommand();frames(*m);
    require(m->params[M::PITCH].getValue()==.1f && m->panelValue(M::PITCH)==.75f && m->sequencer.settings.stages[0].pitch==.75f,"Thru recalls effective pitch without moving physical slider");require(m->params[M::ctrlParam(0,M::CTRL_VALUE)].getValue()==0 && m->sequencer.settings.controls[0].value==.6f && std::abs(m->params[M::trackParam(0,M::GATE_LENGTH)].getValue()-79.4f)<.0001f,"CTRL Thru recalls assignment and effective position without moving physical knob");
    M::PresetRecall receipt;require(m->presetRecalls.pop(receipt) && receipt.pickupBefore[0].active==false && receipt.pickupAfter[0].active && (receipt.pickupMask&257)==257,"load receipt includes exact physical and pickup states");
    m->params[M::PITCH].setValue(.5f);m->params[M::ctrlParam(0,M::CTRL_VALUE)].setValue(.3f);frames(*m);require(m->panelValue(M::PITCH)==.75f && m->sequencer.settings.controls[0].value==.6f,"partial movement does not change recalled pitch or CTRL effect");
    json_t* params=m->paramsToJson(),*data=m->dataToJson();auto copy=make();copy->paramsFromJson(params);copy->dataFromJson(data);require(copy->waitingPickup(M::PITCH) && copy->panelValue(M::PITCH)==.75f && copy->params[M::PITCH].getValue()==.5f,"native patch retains remembered pitch and physical position");auto captured=m->presetFromParamsJson(params,data);require(captured.values[M::PITCH]==.75f && captured.values[M::ctrlParam(0,M::CTRL_VALUE)]==.6f,"actual UI save path stores sounding values while controls wait for pickup");
    copy->params[M::PITCH].setValue(.8f);copy->params[M::ctrlParam(0,M::CTRL_VALUE)].setValue(.7f);frames(*copy);require(!copy->waitingPickup(M::PITCH) && copy->panelValue(M::PITCH)==.8f && copy->sequencer.settings.controls[0].value==.7f,"overshooting saved positions releases each control independently");m->params[M::LOAD_PITCH].setValue(M::PitchOff);frames(*m);require(m->panelValue(M::PITCH)==.5f && !m->waitingPickup(M::PITCH),"Off returns to physical pitch immediately");
    M::PresetCommand undo;undo.kind=M::PresetCommand::Restore;undo.snapshot=receipt.before;undo.other=receipt.after;undo.pickup=receipt.pickupBefore;undo.physical=receipt.physicalBefore;undo.pickupMask=receipt.pickupMask;m->presetCommands.push(undo);frames(*m);require(m->params[M::PITCH].getValue()==.1f && !m->waitingPickup(M::PITCH) && m->integer(M::ctrlParam(0,M::CTRL_DESTINATION))==metro::CtrlNone,"load undo restores physical controls, targets and assignments");
    m->params[M::LOAD_PITCH].setValue(M::PitchThru);undo.snapshot=receipt.after;undo.other=receipt.before;undo.pickup=receipt.pickupAfter;undo.physical=receipt.physicalAfter;m->presetCommands.push(undo);frames(*m);require(m->params[M::PITCH].getValue()==.1f && m->waitingPickup(M::PITCH) && m->panelValue(M::PITCH)==.75f,"load redo restores the latched target instead of jumping the slider");
    json_object_set_new(data,"schemaVersion",json_integer(25));copy->paramsFromJson(params);copy->params[M::LOAD_PITCH].setValue(1);copy->params[M::LOAD_CTRL].setValue(2);copy->dataFromJson(data);require(copy->integer(M::LOAD_PITCH)==M::PitchJump && copy->integer(M::LOAD_CTRL)==M::CtrlJump && !copy->waitingPickup(M::PITCH),"legacy Jump preferences migrate to expanded hardware-ordered lists");json_decref(params);json_decref(data);
    auto chain=make();chain->params[M::LOAD_PITCH].setValue(M::PitchThru);chain->params[M::PITCH].setValue(.2f);chain->putPreset(0,saved);M::ChainState state;metro::ChainLink link;link.slot=0;state.working.insert(0,link);state.enabled=true;chain->setChainState(state);chain->sendChainCommand();frames(*chain);require(chain->params[M::PITCH].getValue()==.2f && chain->panelValue(M::PITCH)==.75f,"chain first link uses the same physical pickup recall path");
    auto live=make();live->params[M::RUN].setValue(1);live->params[M::CLOCK_SOURCE].setValue(2);live->inputs[M::CLOCK_IN].channels=1;frames(*live);auto tick=[&]{live->inputs[M::CLOCK_IN].setVoltage(0);frames(*live,100);live->inputs[M::CLOCK_IN].setVoltage(5);frames(*live,1);};for(int p=0;p<5;++p)tick();int stage=live->sequencer.tracks[0].stage;M::PresetCommand edit;edit.kind=M::PresetCommand::PanelEdit;edit.pickupMask=1;edit.physical[0]=.3f;live->presetCommands.push(edit);frames(*live,1);require(live->sequencer.tracks[0].stage==stage && live->sequencer.tracks[1].stage==stage,"panel undo/redo commands leave sequencer position intact");tick();require(live->sequencer.tracks[0].stage==(stage+1)%8,"panel history does not discard the next external clock edge");
}
